(()=>{const f=facilities.find(x=>x.id==='moe_0210017');if(!f)return;const source='https://hokubukamikita.org/hamanasu/guide';const note='北部上北広域事務組合公式「建設概要」：平成8年7月から平成10年3月施工、52t/日（26t/16h×2炉）、流動床式。設計・製作・施工は川崎重工業株式会社。';if(!f.builder){f.builder='川崎重工業株式会社';f.builder_source=source;f.builder_scope=note;f.builder_research_status='当初設計・製作・施工を組合公式で確認済み';}else{f.builder_additional_research_note=[f.builder_additional_research_note,note].filter(Boolean).join(' ／ ');f.builder_additional_research_urls=[f.builder_additional_research_urls,source].filter(Boolean).join(' | ');}})();